CREATE TABLE t_numeric (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  c_tinyint TINYINT DEFAULT NULL,
  c_smallint_u SMALLINT UNSIGNED DEFAULT NULL,
  c_int INT DEFAULT NULL,
  c_bigint BIGINT DEFAULT NULL,
  c_bigint_u BIGINT UNSIGNED DEFAULT NULL,
  c_decimal DECIMAL(65,30) DEFAULT NULL,
  c_decimal_s DECIMAL(5,2) DEFAULT NULL,
  c_float FLOAT DEFAULT NULL,
  c_double DOUBLE DEFAULT NULL,
  c_bool BOOLEAN DEFAULT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

